/**
 * Action data (640 bytes) retrieved from the PIR database.
 */
public struct ActionData {
    /**
     * enc_ciphertext bytes 52-580 (528 bytes)
     */
    public let encCiphertextTail: Data
    /**
     * out_ciphertext for outgoing viewing key recovery (80 bytes)
     */
    public let outCiphertext: Data
    /**
     * Value commitment (32 bytes)
     */
    public let cv: Data

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * enc_ciphertext bytes 52-580 (528 bytes)
         */encCiphertextTail: Data, 
        /**
         * out_ciphertext for outgoing viewing key recovery (80 bytes)
         */outCiphertext: Data, 
        /**
         * Value commitment (32 bytes)
         */cv: Data) {
        self.encCiphertextTail = encCiphertextTail
        self.outCiphertext = outCiphertext
        self.cv = cv
    }
}

#if compiler(>=6)
extension ActionData: Sendable {}
#endif


extension ActionData: Equatable, Hashable {
    public static func ==(lhs: ActionData, rhs: ActionData) -> Bool {
        if lhs.encCiphertextTail != rhs.encCiphertextTail {
            return false
        }
        if lhs.outCiphertext != rhs.outCiphertext {
            return false
        }
        if lhs.cv != rhs.cv {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(encCiphertextTail)
        hasher.combine(outCiphertext)
        hasher.combine(cv)
    }
}



