                cv: FfiConverterData.read(from: &buf)
        )
    }

    public static func write(_ value: ActionData, into buf: inout [UInt8]) {
        FfiConverterData.write(value.encCiphertextTail, into: &buf)
        FfiConverterData.write(value.outCiphertext, into: &buf)
        FfiConverterData.write(value.cv, into: &buf)
