/**
 * Errors that can occur during PIR operations.
 */
public enum CryptoError: Swift.Error {

    
    
    case InvalidParams(String
    )
    case NotInitialized
    case KeysNotReady
    case QueryFailed(String
    )
    case DecryptionFailed(String
    )
    case InvalidResponse(String
    )
    case SerializationError(String
    )
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeCryptoError: FfiConverterRustBuffer {
    typealias SwiftType = CryptoError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> CryptoError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .InvalidParams(
            try FfiConverterString.read(from: &buf)
            )
        case 2: return .NotInitialized
        case 3: return .KeysNotReady
        case 4: return .QueryFailed(
            try FfiConverterString.read(from: &buf)
            )
        case 5: return .DecryptionFailed(
            try FfiConverterString.read(from: &buf)
            )
        case 6: return .InvalidResponse(
            try FfiConverterString.read(from: &buf)
            )
        case 7: return .SerializationError(
            try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: CryptoError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .InvalidParams(v1):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(v1, into: &buf)
            
        
        case .NotInitialized:
            writeInt(&buf, Int32(2))
        
        
        case .KeysNotReady:
            writeInt(&buf, Int32(3))
        
        
        case let .QueryFailed(v1):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(v1, into: &buf)
            
        
        case let .DecryptionFailed(v1):
            writeInt(&buf, Int32(5))
